package com.demo.department.service;

import com.demo.department.entity.Department;
import com.demo.department.repository.DepartmentRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Optional;

@Service
@Transactional(readOnly = true)
@RequiredArgsConstructor
public class DepartmentService {

    private final DepartmentRepository departmentRepository;

    @Transactional
    public Department createDepartment(Department department) {
        return departmentRepository.save(department);
    }

    public Optional<Department> getDepartmentById(Long id) {
        return departmentRepository.findById(id);
    }
}

package com.demo.department.service;

import com.demo.department.dto.DepartmentResponseDto;
import com.demo.department.entity.Department;
import com.demo.department.repository.DepartmentRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Optional;

@Service
@Transactional(readOnly = true)
@RequiredArgsConstructor
public class DepartmentService {

    private final DepartmentRepository departmentRepository;

    @Transactional
    public DepartmentResponseDto createDepartment(Department department) {
        Department saved = departmentRepository.save(department);
        return toDto(saved);
    }

    public Optional<DepartmentResponseDto> getDepartmentById(Long id) {
        return departmentRepository.findById(id).map(this::toDto);
    }

    private DepartmentResponseDto toDto(Department d) {
        return DepartmentResponseDto.builder()
                .id(d.getId())
                .name(d.getName())
                .code(d.getCode())
                .description(d.getDescription())
                .build();
    }
}

package com.demo.employee.client;

import com.demo.employee.dto.DepartmentDto;
import com.demo.employee.exception.DepartmentServiceException;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientException;

/** Calls the department-service REST API. Single responsibility: HTTP communication only. */
@Slf4j
@Component
@RequiredArgsConstructor
public class DepartmentServiceClient {

    private final RestClient departmentRestClient;

    public DepartmentDto getDepartmentById(Long id) {
        try {
            return departmentRestClient.get()
                    .uri("/api/departments/{id}", id)
                    .retrieve()
                    .body(DepartmentDto.class);
        } catch (RestClientException ex) {
            log.error("Failed to fetch department id={}: {}", id, ex.getMessage());
            throw new DepartmentServiceException(
                    "Department service unavailable while fetching department id=" + id);
        }
    }
}

package com.demo.employee.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.client.RestClient;

@Configuration
public class RestClientConfig {

    @Value("${department.service.base-url}")
    private String departmentServiceBaseUrl;

    /** RestClient pre-configured with the department-service base URL. */
    @Bean
    public RestClient departmentRestClient() {
        return RestClient.builder()
                .baseUrl(departmentServiceBaseUrl)
                .build();
    }
}

package com.demo.employee.dto;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/** Maps the JSON response received from department-service. */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class DepartmentDto {
    private Long id;
    private String name;
    private String code;
    private String description;
}

package com.demo.employee.dto;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/** Combined response for GET /api/employees/{id}/details. */
@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class EmployeeDetailsDto {

    private Long id;
    private String name;            // firstName + lastName
    private DepartmentInfo department;

    @Data
    @NoArgsConstructor
    @AllArgsConstructor
    public static class DepartmentInfo {
        private Long id;
        private String departmentName;  // mapped from DepartmentDto.name
    }
}

package com.demo.employee.exception;

/** Thrown when the department-service is unreachable or returns an error. */
public class DepartmentServiceException extends RuntimeException {
    public DepartmentServiceException(String message) {
        super(message);
    }
}

package com.demo.employee.exception;

import jakarta.persistence.EntityNotFoundException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.time.Instant;
import java.util.Map;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(EntityNotFoundException.class)
    public ResponseEntity<Map<String, Object>> handleNotFound(EntityNotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
                .body(errorBody(HttpStatus.NOT_FOUND, ex.getMessage()));
    }

    @ExceptionHandler(DepartmentServiceException.class)
    public ResponseEntity<Map<String, Object>> handleDeptServiceDown(DepartmentServiceException ex) {
        return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE)
                .body(errorBody(HttpStatus.SERVICE_UNAVAILABLE, ex.getMessage()));
    }

    private Map<String, Object> errorBody(HttpStatus status, String message) {
        return Map.of(
                "timestamp", Instant.now().toString(),
                "status", status.value(),
                "error", status.getReasonPhrase(),
                "message", message
        );
    }
}

